        "conteudo": "Capítulo 92 \r\nJeová está em posição elevada para sempre\r\nSuas obras grandiosas e pensamentos profundos (5)\r\n‘Os justos florescerão como uma árvore’ (12)\r\nIdosos continuarão a dar fruto (14)\r\n\nCapítulo 93 \r\nMajestoso reinado de Jeová\r\n“Jeová tornou-se Rei!” (1)\r\n‘Tuas advertências são confiáveis’ (5)\r\n\nCapítulo 94 \r\nOração por vingança da parte de Deus\r\n“Até quando os maus continuarão?” (3)\r\nA correção de Jah resulta em felicidade (12)\r\nDeus não desamparará o seu povo (14)\r\n“Em nome da lei, trama a desgraça” (20)\r\n\nCapítulo 95 \r\nAdoração verdadeira acompanhada de obediência\r\n“Hoje, se vocês escutarem a voz dele” (7)\r\n“Não endureçam o coração” (8)\r\n“Não entrarão no meu descanso” (11)\r\n\nCapítulo 96 \r\n“Cantem a Jeová um novo cântico”\r\nJeová é digno de todo louvor (4)\r\nOs deuses dos povos não têm valor (5)\r\nAdorem com vestes santas (9)",
