        "conteudo": "M. Jesus é traído, morto e sepultado (26:1–27:66)\r\n\r\nSacerdotes planejam matar Jesus (26:1-5)\r\n\r\nMulher derrama óleo perfumado em Jesus (26:6-13)\r\n\r\nÚltima Páscoa de Jesus; Judas trai Jesus (26:14-25)\r\n\r\nPrimeira Ceia do Senhor (26:26-30)\r\n\r\nJesus prediz que Pedro vai negá-lo (26:31-35)\r\n\r\nJesus ora em Getsêmani (26:36-46)\r\n\r\nJesus é detido e levado ao Sinédrio (26:47-68)\r\n\r\nPedro nega Jesus três vezes e chora amargamente (26:69-75)\r\n\r\nSacerdotes e anciãos entregam Jesus a Pilatos (27:1, 2)\r\n\r\nJudas sente remorso e se enforca (27:3-10)\r\n\r\nPilatos interroga Jesus (27:11-26)\r\n\r\nSoldados zombam de Jesus em público (27:27-31)\r\n\r\nJesus é pregado numa estaca em Gólgota (27:32-44)\r\n\r\nJesus morre (27:45-56)\r\n\r\nJesus é sepultado (27:57-61)\r\n\r\nSepultura de Jesus é lacrada e vigiada (27:62-66)\r\n\r\nN. Jesus é ressuscitado; dá a ordem de fazer discípulos (28:1-20)\r\n\r\nJesus é ressuscitado; aparece para seus discípulos (28:1-10)\r\n\r\nSoldados aceitam suborno para mentir sobre a ressurreição de Jesus (28:11-15)\r\n\r\nJesus dá a ordem de fazer discípulos (28:16-20)",
