        "conteudo": "C. Jesus ensina usando ilustrações (4:1-34)\r\n\r\nDe um barco, Jesus ensina grandes multidões (4:1, 2)\r\n\r\nIlustração do semeador e dos quatro tipos de solo (4:3-9)\r\n\r\nPor que Jesus usou ilustrações (4:10-13)\r\n\r\nExplicação da ilustração do semeador (4:14-20)\r\n\r\nNão se coloca uma lâmpada debaixo de um cesto (4:21-23)\r\n\r\n“A mesma medida com que vocês medem” (4:24, 25)\r\n\r\nIlustração do semeador que dorme (4:26-29)\r\n\r\nIlustração do grão de mostarda (4:30-32)\r\n\r\nUso de ilustrações (4:33, 34)\r\n\r\nD. Jesus faz vários milagres, no mar da Galileia e na região ao redor (4:35–5:43)\r\n\r\nJesus acalma uma tempestade violenta (4:35-41)\r\n\r\nJesus cura um homem possesso de demônios; permite que os demônios entrem nos porcos (5:1-20)\r\n\r\nRessuscita filha de Jairo; uma mulher toca na roupa de Jesus (5:21-43)\r\n\r\nE. Jesus expande seu ministério na Galileia e visita regiões ao norte e ao leste (6:1–9:50)\r\n\r\nJesus é rejeitado em sua própria cidade (6:1-6)\r\n\r\nJesus dá instruções aos Doze sobre o ministério e os envia (6:7-13)\r\n\r\nMorte de João, o Batizador (6:14-29)\r\n\r\nJesus alimenta cerca de 5.000 homens (6:30-44)\r\n\r\nJesus anda sobre a água (6:45-52)\r\n\r\nCuras em Genesaré (6:53-56)",
