        "data": "31/10",
        "livro": "João 7-9",
        "escritor": "Apóstolo João",
        "lugar": "Éfeso, ou perto dali",
        "escrita": "c. 98",
        "tempo": "Depois do prólogo, 29-33 d.C.",
        "conteudo": "H. Da época da Festividade das Tendas de 32 d.C. em diante (7:2–9:41)\n\nIrmãos de Jesus sobem para a festividade; Jesus vai depois e chega na cidade em segredo (7:2-13)\n\nJesus ensina no templo durante a festividade (7:14-24)\n\nPessoas têm opiniões diferentes sobre o Cristo (7:25-52)\n\nO Pai dá testemunho sobre Jesus, “a luz do mundo” (8:12-30)\n\nVerdadeiros discípulos de Jesus conhecerão a verdade (8:31, 32)\n\nFilhos de Abraão fazem as obras de Abraão (8:33-41)\n\nFilhos do Diabo fazem o que o Diabo deseja (8:42-47)\n\nJesus e Abraão (8:48-59)\n\nJesus cura um homem que nasceu cego (9:1-12)\n\nFariseus interrogam o homem que foi curado (9:13-34)\n\nCegueira dos fariseus (9:35-41)",
        "videos": []
