        "escrita": "c. 98",
        "tempo": "Depois do prólogo, 29-33 d.C.",
        "conteudo": "I. Da época da Festividade da Dedicação de 32 d.C. a 10 de nisã de 33 d.C. (10:1–12:50)\r\n\r\nIlustração do pastor e dos apriscos (10:1-18)\r\n\r\nMuitos judeus se recusam a acreditar (10:19-26)\r\n\r\nJesus e seu Pai estão unidos em cuidar das ovelhas (10:27-30)\r\n\r\nJudeus tentam prender Jesus (10:31-39)\r\n\r\nMuitas pessoas do outro lado do Jordão depositam fé em Jesus (10:40-42)\r\n\r\nMorte de Lázaro (11:1-16)\r\n\r\nJesus consola Marta e Maria (11:17-37)\r\n\r\nJesus ressuscita Lázaro (11:38-44)\r\n\r\nLíderes religiosos planejam matar Jesus (11:45-57)\r\n\r\nMaria derrama óleo perfumado nos pés de Jesus (12:1-11)\r\n\r\nEntrada triunfal de Jesus em Jerusalém (12:12-19)\r\n\r\nJesus prediz que sua morte está próxima (12:20-27)\r\n\r\nUma voz do céu (12:28)\r\n\r\nFalta de fé dos judeus cumpre profecia (12:29-43)\r\n\r\nJesus veio salvar o mundo (12:44-50)",
