        "lugar": "Éfeso, ou perto dali",
        "escrita": "c. 98",
        "tempo": "Depois do prólogo, 29-33 d.C.",
        "conteudo": "J. Última Páscoa de Jesus e últimos conselhos para seus discípulos (13:1–17:26)\r\n\r\nJesus lava os pés dos discípulos (13:1-20)\r\n\r\nJesus identifica seu traidor: Judas Iscariotes (13:21-30)\r\n\r\nJesus dá um novo mandamento (13:31-35)\r\n\r\nJesus prediz que Pedro vai negá-lo três vezes (13:36-38)\r\n\r\nJesus é o único caminho para se chegar ao Pai (14:1-14)\r\n\r\nJesus promete que o espírito santo virá como ajudador (14:15-31)\r\n\r\nIlustração da verdadeira videira (15:1-10)\r\n\r\nMandamento para amar como Cristo amou (15:11-17)\r\n\r\nMundo odeia Jesus e seus discípulos (15:18-27)",
