        "conteudo": "Capítulo 1\r\n\r\nSaudações (1, 2)\r\n\r\nPaulo agradece a Deus pela fé que Timóteo tem (3-5)\r\n\r\nMantenha aceso o dom de Deus (6-11)\r\n\r\nApegue-se a palavras sadias (12-14)\r\n\r\nOs inimigos e os amigos de Paulo (15-18)\r\n\r\nCapítulo 2\r\n\r\nConfie a mensagem a homens qualificados (1-7)\r\n\r\nSuportar sofrimento pelas boas novas (8-13)\r\n\r\nManeje corretamente a palavra de Deus (14-19)\r\n\r\nFuja dos desejos da juventude (20-22)\r\n\r\nComo lidar com opositores (23-26)\r\n\r\nCapítulo 3\r\n\r\nTempos críticos nos últimos dias (1-7)\r\n\r\nSeguir atentamente o exemplo de Paulo (8-13)\r\n\r\n“Continue nas coisas que aprendeu” (14-17)\r\n\r\nToda a Escritura é inspirada por Deus (16)\r\n\r\nCapítulo 4\r\n\r\n“Realize plenamente o seu ministério” (1-5)\r\n\r\nPregue a palavra urgentemente (2)\r\n\r\n“Travei a boa luta” (6-8)\r\n\r\nObservações pessoais (9-18)\r\n\r\nSaudações finais (19-22)",
